`timescale 1ns/1ps
module tb_sample_poly_cbd_pipe #(parameter integer ETA=2,parameter integer VECTORS=128);reg clk=0,rst_n=0,start=0,iv=0,last=0,ordy=1;reg[31:0]id;wire busy,done,error,ir,ov;wire[11:0]oc;wire[7:0]oi;wire[1:0]dom;integer fd,rc,v,w,i,got,checks=0;reg[31:0]words[0:47];reg[11:0]exp[0:255];string file;always#5 clk=~clk;sample_poly_cbd_pipe dut(clk,rst_n,start,ETA,busy,done,error,iv,ir,id,4'hf,last,ov,ordy,oc,oi,dom);
 initial begin if(!$value$plusargs("VECTOR_FILE=%s",file))$fatal(1,"VECTOR_FILE");fd=$fopen(file,"r");repeat(3)@(negedge clk);rst_n=1;for(v=0;v<VECTORS;v=v+1)begin for(w=0;w<16*ETA;w=w+1)rc=$fscanf(fd,"%h\n",words[w]);for(i=0;i<256;i=i+1)rc=$fscanf(fd,"%h\n",exp[i]);@(negedge clk);start=1;@(negedge clk);start=0;got=0;for(w=0;w<16*ETA;w=w+1)begin while(!ir)@(negedge clk);iv=1;id=words[w];last=(w==16*ETA-1);@(negedge clk);iv=0;last=0;end while(!done)@(negedge clk);if(error||got!=256)$fatal(1,"status");end $display("PASS tb_sample_poly_cbd_pipe eta=%0d vectors=%0d coeff_checks=%0d",ETA,VECTORS,checks);$finish;end
 always@(posedge clk)if(ov&&ordy)begin if(oi!==got[7:0]||oc!==exp[got]||oc>=3329||dom!=2'b01)$fatal(1,"eta=%0d v=%0d i=%0d exp=%0d got=%0d x=%0d y=%0d res=%h bits=%0d words=%0d",ETA,v,got,exp[got],oc,dut.x,dut.y,dut.reservoir,dut.bit_count,dut.words_in);got=got+1;checks=checks+1;end endmodule
